-- CoE tasting-note flavor links (matched from detail-page Aroma/Flavor/Acidity text).
-- Approximate keyword->SCA flavor-wheel mapping. Staging + INSERT..SELECT, OR IGNORE.
DROP TABLE IF EXISTS _coe_flav;
CREATE TABLE _coe_flav (url TEXT, flavor_id TEXT);
CREATE INDEX IF NOT EXISTS idx_coffees_url ON ref_coffees(url);
INSERT OR IGNORE INTO ref_coffee_flavors (coffee_id,flavor_id) SELECT c.id, f.flavor_id FROM _coe_flav f JOIN ref_coffees c ON c.url=f.url;
DROP TABLE _coe_flav;
